using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Racer;using Object=UnityEngine.Object;
public static class InspectReverseFailures {public static string Main(){var rows=new List<string>();for(float x=375;x<396;x+=.5f){float z=-3.1f+(x-389)*.2f;var hits=Physics.RaycastAll(new(x,250,z),Vector3.down,500,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance);rows.Add(x+" "+string.Join("; ",hits.Select(h=>h.collider.name+"="+h.point.y+" normal="+h.normal)));}var objects=Physics.OverlapBox(new(389,89,-3.1f),new(7,5,5),Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(c=>!c.name.StartsWith("Ground_")).Select(c=>c.name+" "+c.bounds);rows.AddRange(objects);File.WriteAllLines("Docs/BackyardReverseCorrections/failure-inspection.txt",rows);return "Inspect pool-house lip collision";}}
